// Photos and manual PDFs. Keys are photo ids or manuals/<id>, both generated by the server.
// Stored as plain files under DATA_DIR/files, or in an S3-compatible bucket when S3_BUCKET is set.
import { AwsClient } from 'aws4fetch';
import { env } from '$env/dynamic/private';
import { createReadStream } from 'node:fs';
import { mkdir, rm, stat, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { Readable } from 'node:stream';
import { DATA_DIR } from './db';
import { parseRange } from './range';

type Stored = { body: ReadableStream; size: number; range: { start: number; end: number } | null };
export type Bucket = {
	put(key: string, body: Blob | ArrayBuffer): Promise<void>;
	// null when missing. With a Range header it serves that part, if it's one range that fits.
	get(key: string, range?: string | null): Promise<Stored | null>;
	delete(keys: string | string[]): Promise<void>;
};

// Keys can come from a URL, so nothing that could step outside the store gets through.
function checkKey(key: string) {
	if (!/^(manuals\/)?[\w-]+$/.test(key)) throw new Error(`Bad storage key: ${key}`);
	return key;
}

const toBytes = async (body: Blob | ArrayBuffer) =>
	new Uint8Array(body instanceof Blob ? await body.arrayBuffer() : body);

function fileBucket(root: string): Bucket {
	const pathFor = (key: string) => join(root, checkKey(key));
	return {
		async put(key, body) {
			const path = pathFor(key);
			await mkdir(dirname(path), { recursive: true });
			await writeFile(path, await toBytes(body));
		},
		async get(key, range) {
			const path = pathFor(key);
			const size = await stat(path).then(
				(s) => s.size,
				() => null
			);
			if (size === null) return null;
			const part = range ? parseRange(range, size) : null;
			const stream = createReadStream(path, part ?? {});
			return { body: Readable.toWeb(stream) as ReadableStream, size, range: part };
		},
		async delete(keys) {
			await Promise.all([keys].flat().map((key) => rm(pathFor(key), { force: true })));
		}
	};
}

// Path-style URLs (endpoint/bucket/key), which AWS, R2, MinIO and the rest all accept.
function s3Bucket(e: Env): Bucket {
	if (!e.S3_ACCESS_KEY_ID || !e.S3_SECRET_ACCESS_KEY) {
		throw new Error(
			'S3_BUCKET is set, so S3_ACCESS_KEY_ID and S3_SECRET_ACCESS_KEY are needed too'
		);
	}
	const aws = new AwsClient({
		accessKeyId: e.S3_ACCESS_KEY_ID,
		secretAccessKey: e.S3_SECRET_ACCESS_KEY,
		region: e.S3_REGION ?? 'auto',
		service: 's3'
	});
	const endpoint = (
		e.S3_ENDPOINT ?? `https://s3.${e.S3_REGION ?? 'us-east-1'}.amazonaws.com`
	).replace(/\/$/, '');
	const url = (key: string) => `${endpoint}/${e.S3_BUCKET}/${checkKey(key)}`;
	const send = async (key: string, init: RequestInit, ok: number[] = []) => {
		const res = await aws.fetch(url(key), init);
		if (!res.ok && !ok.includes(res.status)) {
			throw new Error(`S3 ${init.method} ${key} failed: ${res.status} ${await res.text()}`);
		}
		return res;
	};
	return {
		async put(key, body) {
			await send(key, { method: 'PUT', body: await toBytes(body) });
		},
		async get(key, range) {
			// S3 handles the Range header itself: 206 for one range it can serve, 200 when it ignores
			// it (e.g. several ranges), 416 when it can't be met, which falls back to the whole file.
			let res = await send(key, { method: 'GET', headers: range ? { range } : {} }, [404, 416]);
			if (res.status === 416) res = await send(key, { method: 'GET' }, [404]);
			if (res.status === 404 || !res.body) return null;
			const part = /^bytes (\d+)-(\d+)\/(\d+)$/.exec(res.headers.get('content-range') ?? '');
			if (res.status === 206 && part) {
				const [start, end, size] = part.slice(1).map(Number);
				return { body: res.body, size, range: { start, end } };
			}
			return { body: res.body, size: Number(res.headers.get('content-length')), range: null };
		},
		async delete(keys) {
			await Promise.all([keys].flat().map((key) => send(key, { method: 'DELETE' }, [404])));
		}
	};
}

export const bucket = env.S3_BUCKET ? s3Bucket(env) : fileBucket(join(DATA_DIR, 'files'));
